-- TermPilot schema v19, matching the native macOS persistence contract.
CREATE TABLE "automation_scripts" ("id" TEXT PRIMARY KEY, "payload" BLOB NOT NULL, "updated_at" DATETIME NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "connection_history" ("id" TEXT PRIMARY KEY, "host_id" TEXT REFERENCES "hosts"("id") ON DELETE SET NULL, "started_at" DATETIME NOT NULL, "ended_at" DATETIME, "succeeded" BOOLEAN NOT NULL, "error_category" TEXT);
CREATE TABLE grdb_migrations (identifier TEXT NOT NULL PRIMARY KEY);
CREATE TABLE "host_groups" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "parent_group_id" TEXT REFERENCES "host_groups"("id") ON DELETE SET NULL);
CREATE TABLE "host_notes" ("id" TEXT PRIMARY KEY, "host_id" TEXT REFERENCES "hosts"("id") ON DELETE SET NULL, "payload" BLOB NOT NULL, "updated_at" DATETIME NOT NULL);
CREATE TABLE "hosts" ("id" TEXT PRIMARY KEY, "label" TEXT NOT NULL, "hostname" TEXT NOT NULL, "port" INTEGER NOT NULL, "username" TEXT NOT NULL, "authentication" TEXT NOT NULL, "identity_file" TEXT, "credential_reference" TEXT, "group_id" TEXT REFERENCES "host_groups"("id") ON DELETE SET NULL, "created_at" DATETIME NOT NULL, "updated_at" DATETIME NOT NULL, "password" TEXT, "sftp_file_protocol" TEXT NOT NULL DEFAULT 'auto', "sftp_filename_encoding" TEXT NOT NULL DEFAULT 'auto', "sftp_uses_sudo" BOOLEAN NOT NULL DEFAULT 0, "sftp_follows_terminal_cwd" BOOLEAN, "proxy_profile_reference" TEXT, "proxy_type" TEXT, "proxy_host" TEXT, "proxy_port" INTEGER, "proxy_command" TEXT, "proxy_credential_reference" TEXT, "proxy_username" TEXT, "proxy_password" TEXT, "distro" TEXT, "distro_mode" TEXT NOT NULL DEFAULT 'auto', "manual_distro" TEXT, "icon_mode" TEXT NOT NULL DEFAULT 'auto', "icon_id" TEXT, "icon_color_mode" TEXT NOT NULL DEFAULT 'auto', "icon_color" TEXT, "icon_color_custom" TEXT, "server_tools_use_root" BOOLEAN NOT NULL DEFAULT 0, "server_tools_elevation_method" TEXT NOT NULL DEFAULT 'sudo', "sort_order" INTEGER NOT NULL DEFAULT 0, "connection_kind" TEXT NOT NULL DEFAULT 'ssh');
CREATE TABLE "port_forward_rules" ("id" TEXT PRIMARY KEY, "host_id" TEXT REFERENCES "hosts"("id") ON DELETE SET NULL, "payload" BLOB NOT NULL, "updated_at" DATETIME NOT NULL);
CREATE TABLE "screen_sharing_profiles" ("host_id" TEXT PRIMARY KEY REFERENCES "hosts"("id") ON DELETE CASCADE, "port" INTEGER NOT NULL DEFAULT 5900, "username" TEXT NOT NULL, "password" TEXT, "audio" BOOLEAN NOT NULL DEFAULT 1, "mode" TEXT NOT NULL DEFAULT 'highPerformance');
CREATE TABLE "snippets" ("id" TEXT PRIMARY KEY, "payload" BLOB NOT NULL, "updated_at" DATETIME NOT NULL);
CREATE TABLE "ssh_credentials" ("id" TEXT PRIMARY KEY, "label" TEXT NOT NULL, "username" TEXT NOT NULL, "kind" TEXT NOT NULL, "password" TEXT, "private_key" TEXT, "public_key" TEXT, "certificate" TEXT, "passphrase" TEXT, "saves_passphrase" BOOLEAN NOT NULL DEFAULT 0, "created_at" DATETIME NOT NULL, "updated_at" DATETIME NOT NULL, "elevation_password" TEXT, "elevation_method" TEXT);
CREATE TABLE "ssh_proxy_profiles" ("id" TEXT PRIMARY KEY, "label" TEXT NOT NULL, "type" TEXT NOT NULL, "host" TEXT NOT NULL, "port" INTEGER NOT NULL, "command" TEXT, "credential_reference" TEXT, "username" TEXT, "password" TEXT, "created_at" DATETIME NOT NULL, "updated_at" DATETIME NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "workspace_state" ("id" INTEGER PRIMARY KEY, "payload" BLOB NOT NULL, "saved_at" DATETIME NOT NULL);
CREATE INDEX "host_notes_host" ON "host_notes"("host_id");
CREATE INDEX "hosts_search" ON "hosts"("label", "hostname", "username");
CREATE INDEX "port_forward_rules_host" ON "port_forward_rules"("host_id");
CREATE INDEX "ssh_credentials_label" ON "ssh_credentials"("label");
CREATE INDEX "ssh_proxy_profiles_label" ON "ssh_proxy_profiles"("label");
